from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

# TASK 1: Find min of two corresponding elements
@task(returns=float)
def min_element(a, b):
    return min(a, b)

# TASK 2: Add two numbers (used for reduction)
@task(returns=float)
def add_pair(a, b):
    return a + b

def main(x, y):
    """
    Computes sum(min(x[i], y[i])) for all i.
    Uses 'No Chunking' strategy:
    1. One task per index to find the min.
    2. Tree reduction to sum the results.
    """
    if not x or not y:
        return 0.0

    # Ensure lengths match (handling edge cases simply)
    n = min(len(x), len(y))

    # Phase 1: Map - Calculate minimums for all indices in parallel
    min_values = []
    for i in range(n):
        # Launch task for every pair
        val = min_element(x[i], y[i])
        min_values.append(val)

    # Phase 2: Reduce - Sum the results using Tree strategy
    working_list = min_values

    while len(working_list) > 1:
        new_level = []
        for i in range(0, len(working_list), 2):
            if i + 1 < len(working_list):
                # Sum the pair
                s = add_pair(working_list[i], working_list[i+1])
                new_level.append(s)
            else:
                # Carry over the last element
                new_level.append(working_list[i])
        working_list = new_level

    # Wait for the final single result
    return compss_wait_on(working_list[0])
